// Build the Anthropic /v1/messages request payload.
// Inputs available:
//   $('When Called by W1').first().json  -> { user_id, chat_id, message_text, is_admin }
//   $('Load History').all()              -> rows of {role, content}, newest first
//   $('Load Active Habits').all()        -> rows of {name, cadence, target_per_week, description}

const trigger = $('When Called by W1').first().json;
const historyRows = $('Load History').all().map(i => i.json);
const habitRows = $('Load Active Habits').all().map(i => i.json);

// Conversation history -> oldest first, only user+assistant rows for now
const messages = historyRows
  .filter(r => r.role === 'user' || r.role === 'assistant')
  .reverse()
  .map(r => ({ role: r.role, content: r.content }));

// Append the current user turn
messages.push({ role: 'user', content: trigger.message_text });

// Build active habits list for system prompt
const habitList = habitRows.length
  ? habitRows.map(h => `- ${h.name} (${h.cadence}${h.target_per_week ? `, target ${h.target_per_week}/wk` : ''})${h.description ? ' — ' + h.description : ''}`).join('\n')
  : '(none yet)';

const now = new Date().toLocaleString('en-CA', { timeZone: 'America/Toronto' });

const system = `You are Jarvis, Mark's personal assistant. Be concise and friendly.

Current time (Toronto): ${now}
User: Mark Freedman

Mark's active habits:
${habitList}

You have two tools available, but use them sparingly and only when clearly applicable:

- create_habit: ONLY when Mark explicitly says he wants to START tracking a new habit. Trigger phrases: "I want to start...", "add X to my habits", "begin tracking Y". Do NOT auto-create habits from casual mentions.

- log_habit: ONLY when Mark explicitly states he just COMPLETED a habit in the past tense. Trigger phrases: "I just X'd", "finished my Y", "logged a Z", "did 30 min of W". Must be a clear past-tense action statement.

DO NOT call log_habit for questions like "did I X today?" or "how many X this week?" — those are queries, not completions. Just answer the question directly using the conversation history and active habits list.

DO NOT call log_habit for hypothetical/future statements like "I should X tomorrow" or "reminding myself to Y".

When unsure, ask one clarifying question instead of calling a tool. For everything else, just chat naturally.`;

const tools = [
  {
    name: 'create_habit',
    description: 'Create a new habit Mark wants to track. Use when he says things like "I want to start meditating daily" or "add running 3x a week".',
    input_schema: {
      type: 'object',
      properties: {
        name:            { type: 'string',  description: 'Short habit name, lowercase preferred' },
        description:     { type: 'string',  description: 'Optional longer description' },
        cadence:         { type: 'string',  enum: ['daily', 'weekly', 'custom'], description: 'How often' },
        target_per_week: { type: 'integer', description: 'Times per week, 1-7', minimum: 1, maximum: 7 }
      },
      required: ['name', 'cadence']
    }
  },
  {
    name: 'log_habit',
    description: 'Log that Mark completed an existing habit. Use when he says "I just meditated" or "logged a run".',
    input_schema: {
      type: 'object',
      properties: {
        habit_name: { type: 'string', description: 'Name of an existing habit (case-insensitive match)' },
        note:       { type: 'string', description: 'Optional note about this completion' }
      },
      required: ['habit_name']
    }
  }
];

return [{
  json: {
    body: {
      model:      'claude-sonnet-4-5-20250929',
      max_tokens: 1024,
      system,
      tools,
      messages
    },
    // Carry through for downstream nodes
    user_id:      trigger.user_id,
    chat_id:      trigger.chat_id,
    message_text: trigger.message_text
  }
}];

// Inspect Claude response. Decide: text-only or tool_use?
const resp = $json;
const trigger = $('Build Claude Request').first().json;

const stopReason = resp.stop_reason;
const contentBlocks = resp.content || [];

const textBlock = contentBlocks.find(b => b.type === 'text');
const toolUseBlock = contentBlocks.find(b => b.type === 'tool_use');

return [{
  json: {
    stop_reason:    stopReason,
    has_tool_use:   !!toolUseBlock,
    tool_use_id:    toolUseBlock ? toolUseBlock.id : null,
    tool_name:      toolUseBlock ? toolUseBlock.name : null,
    tool_input:     toolUseBlock ? toolUseBlock.input : null,
    text:           textBlock ? textBlock.text : '',
    raw_assistant_msg: { role: 'assistant', content: contentBlocks },
    user_id:        trigger.user_id,
    chat_id:        trigger.chat_id,
    message_text:   trigger.message_text,
    original_messages: trigger.body.messages
  }
}];

