INSERT INTO habits (user_id, name, description, cadence, target_per_week)
VALUES (
  current_user_id(),
  '{{ $json.tool_input.name }}',
  {{ $json.tool_input.description ? "'" + $json.tool_input.description.replace(/'/g, "''") + "'" : 'NULL' }},
  '{{ $json.tool_input.cadence }}',
  {{ $json.tool_input.target_per_week || 7 }}
)
RETURNING id, name, cadence, target_per_week;

