// Combine the tool result with the original conversation, then build the second Claude call payload.
const toolRow = $json; // from create_habit OR log_habit insert
const parsed = $('Parse Claude Response').first().json;
const originalReq = $('Build Claude Request').first().json;

// Format the tool_result content for Claude.
// For create_habit success row has: id, name, cadence, target_per_week
// For log_habit success row has: name, completed_at, total_logs (or empty if no match)
let toolResultText;
let isError = false;
if (parsed.tool_name === 'create_habit') {
  if (toolRow && toolRow.id) {
    toolResultText = `Created habit "${toolRow.name}" (${toolRow.cadence}, target ${toolRow.target_per_week}/wk).`;
  } else {
    toolResultText = 'Failed to create habit.';
    isError = true;
  }
} else if (parsed.tool_name === 'log_habit') {
  if (toolRow && toolRow.completed_at) {
    toolResultText = `Logged "${toolRow.name}" at ${toolRow.completed_at}. Total completions: ${toolRow.total_logs}.`;
  } else if (toolRow && toolRow.name) {
    toolResultText = `Found habit "${toolRow.name}" but log insert failed.`;
    isError = true;
  } else {
    toolResultText = `No active habit named "${parsed.tool_input.habit_name}". Suggest creating one first.`;
    isError = true;
  }
}

// Build the next messages array: original + assistant's tool_use turn + user tool_result turn
const nextMessages = [
  ...parsed.original_messages,
  parsed.raw_assistant_msg,
  {
    role: 'user',
    content: [
      {
        type: 'tool_result',
        tool_use_id: parsed.tool_use_id,
        content: toolResultText,
        is_error: isError
      }
    ]
  }
];

return [{
  json: {
    body: {
      model:      originalReq.body.model,
      max_tokens: originalReq.body.max_tokens,
      system:     originalReq.body.system,
      tools:      originalReq.body.tools,
      messages:   nextMessages
    },
    user_id:      parsed.user_id,
    chat_id:      parsed.chat_id,
    message_text: parsed.message_text
  }
}];

// Extract final assistant text from the second Claude call.
const resp = $json;
const trigger = $('Build Tool Result Request').first().json;
const textBlock = (resp.content || []).find(b => b.type === 'text');
return [{
  json: {
    final_text: textBlock ? textBlock.text : '(no reply)',
    user_id:    trigger.user_id,
    chat_id:    trigger.chat_id,
    message_text: trigger.message_text
  }
}];

// end_turn branch — already have text from Parse Claude Response.
const parsed = $json;
return [{
  json: {
    final_text:   parsed.text || '(no reply)',
    user_id:      parsed.user_id,
    chat_id:      parsed.chat_id,
    message_text: parsed.message_text
  }
}];
